sys_ux_data_broker_transform.script:
function transform(input) {
    var otline = new GlideRecord('x_1120851_ottrack_ot_request_line');
    var otrequest = new GlideRecord('x_1120851_ottrack_ot_request');

    var requestId = input.requestId;
    var groupId = input.groupId;

	gs.info("request ID: " + requestId);

    otrequest.get(requestId);
    var gr = new GlideRecord('sys_user_grmember');
    gr.addQuery('group', groupId);
    gr.query();
    while (gr.next()) {
        var user = gr.getValue('user');

        var ga = new GlideAggregate('x_1120851_ottrack_ot_log');
        ga.addQuery('employee', user);
        ga.addAggregate('SUM', 'hours_worked');
        ga.query();

        var totalHours = 0;
        if (ga.next()) {
            totalHours = parseFloat(ga.getAggregate('SUM', 'hours_worked'));
        }

        otline.initialize();
        otline.employee = user;
        otline.ot_request = requestId;
        otline.cumulative_ot_hours = totalHours;
        otline.insert();
    }
}
